export interface LaunchOptions {
  debug: boolean;
  courseId?: string;
  hole?: number;
}

export function parseLaunchOptions(search: string): LaunchOptions {
  const p = new URLSearchParams(search);
  const courseId = p.get('course')?.trim() || undefined;
  const n = Number(p.get('hole'));
  const hole = Number.isInteger(n) && n > 0 ? n : undefined;
  return {
    debug: p.get('debug') === '1',
    ...(courseId ? {courseId} : {}),
    ...(hole ? {hole} : {}),
  };
}
